const phone = {
  owner: "Kim",
  ring() {
    return `${this.owner} gets a call`;
  },
};

const ring = phone.ring;
const tablet = { owner: "Sam", ring };

console.log(phone.ring());

try {
  console.log(ring());
} catch (error) {
  console.log(error.name);
}

console.log(tablet.ring());
